+#include <charconv>
+#include <system_error>
+#endif
+
 extern "C" size_t parse_doubles(const char* buf, size_t len, double* out) {
     const char* p = buf;
     const char* end = buf + len;
     size_t count = 0;
     while (p < end) {
+        // Locate the newline that terminates the current number.
+        const char* nl = static_cast<const char*>(std::memchr(p, '\n', end - p));
+        if (!nl) break; // Should never happen with valid input.
+
+        double value;
+#if defined(__cpp_lib_charconv)
+        auto res = std::from_chars(p, nl, value);
+        if (res.ec != std::errc()) {
+            // Fallback to strtod for any parsing error (should be rare).
+            char* next;
+            value = std::strtod(p, &next);
+        }
+#else
         char* next;
-        out[count++] = std::strtod(p, &next);
-        p = next;
-        while (p < end && *p == '\n') ++p;
+        value = std::strtod(p, &next);
+#endif
+        out[count++] = value;
+        p = nl + 1; // Advance past the newline.
     }
     return count;
 }
